arguments.command:
cat > tests/prune_test.sh <<'EOF'
#!/bin/bash
fail=0
d=$(mktemp -d)
mkdir -p "$d/logs"
for i in 1 2 3 4 5 6; do echo "v$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log "2026100$i"; done
echo x > "$d/logs/other.log.9"; echo y > "$d/archive/other.log.20260101"
[ "$(ls "$d/logs" | grep -c '^app\.log\.[0-9]*$')" = 3 ] || { echo "local count"; fail=1; }
[ -e "$d/logs/app.log.4" ] && { echo "app.log.4 remains"; fail=1; }
[ "$(cat "$d/logs/app.log.3")" = v4 ] || { echo "local keeps newest"; fail=1; }
[ "$(ls "$d/archive" | grep -c '^app\.log\.[0-9]\{8\}$')" = 3 ] || { echo "archive count"; fail=1; }
[ -e "$d/archive/app.log.20261006" ] && [ -e "$d/archive/app.log.20261004" ] && [ ! -e "$d/archive/app.log.20261003" ] || { echo "archive newest"; fail=1; }
[ -e "$d/logs/other.log.9" ] && [ -e "$d/archive/other.log.20260101" ] || { echo "other names untouched"; fail=1; }
rm -rf "$d"
exit $fail
EOF
cat >> lib/local.sh <<'EOF'

# read_keep: print keep from config/rotate.conf.
read_keep() {
  sed -n 's/^keep=\([0-9][0-9]*\)$/\1/p' "$root/config/rotate.conf" | tail -n 1
}

# prune_local <dir> <name> <keep>: delete name.N for N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".*; do
    n=${f##*/"$name".}
    case $n in ''|*[!0-9]*) continue;; esac
    [ "$n" -gt "$keep" ] && rm -f "$f"
  done
}
EOF
cat >> lib/archive.sh <<'EOF'

# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<YYYYMMDD>.
prune_archive() {
  local archive=$1 name=$2 keep=$3 f
  ls "$archive" | grep "^$name\.[0-9]\{8\}$" | sort -r | tail -n +$((keep + 1)) |
    while read -r f; do rm -f "$archive/$f"; done
}
EOF
cat >> bin/rotate <<'EOF'
keep=$(read_keep)
[ -n "$keep" ] && [ "$keep" -ge 1 ] || { echo "rotate: invalid keep in config/rotate.conf" >&2; exit 1; }
prune_local "$1" "$3" "$keep"
prune_archive "$2" "$3" "$keep"
EOF
bash scripts/verify.sh; echo rc=$?

